from openpyxl import load_workbook

wb = load_workbook("budget.xlsx", data_only=True)
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims={ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ===")
    for row in ws.iter_rows():
        vals = [(c.coordinate, c.value) for c in row if c.value is not None]
        if vals:
            print(vals)

import zipfile, shutil, sys
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}
M = NS['m']

def q(tag):
    return f'{{{M}}}{tag}'

def cell_value(cell, shared, styles):
    t = cell.get('t')
    v = cell.find(q('v'))
    if v is None or v.text is None:
        return None
    text = v.text
    if t == 's':
        return shared[int(text)]
    if t == 'b':
        return text == '1'
    if t == 'inlineStr':
        is_ = cell.find(q('is'))
        return ''.join(x.text or '' for x in is_.iter(q('t'))) if is_ is not None else None
    if t == 'str':
        return text
    return text  # numeric or formula cached value

def main(path):
    print("soffice available:", shutil.which('soffice'))
    z = zipfile.ZipFile(path)
    print("zip entries:", z.namelist())

    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall(q('si')):
            shared.append(''.join(t.text or '' for t in si.iter(q('t'))))

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = wb_root.find(q('sheets'))
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rels = {r.get('Id'): r.get('Target') for r in rels_root}

    for sh in sheets.findall(q('sheet')):
        rid = sh.get(f'{{{NS["r"]}}}id')
        target = rels[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        print(f"\n=== Sheet: {sh.get('name')} ({target}) ===")
        sroot = ET.fromstring(z.read(target))
        sd = sroot.find(q('sheetData'))
        if sd is None:
            print("(empty)")
            continue
        for row in sd.findall(q('row')):
            vals = []
            for c in row.findall(q('c')):
                cv = cell_value(c, shared, None)
                if cv is not None:
                    vals.append((c.get('r'), cv))
            if vals:
                print(vals)

if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else 'budget.xlsx')

